        // Set up the LogFile address in c before initializing c, so Collect has a valid Log target.
        c.SetLogFile(logAddr);
        c.Initialized();
        c.Deposit{value: depAmt}();

        // Record the LogFile History length before Collect by reading the last message time.
        beforeLen = LogFile(logAddr).History(0).Time;

        // Perform the deciding Collect call.
        c.Collect(colAmt);

        // Record the LogFile History length after Collect.
        afterLen = LogFile(logAddr).History(1).Time;

        assert(afterLen != beforeLen);
    }

    receive() external payable {}
}

